from fastapi import APIRouter, Depends, HTTPException

router = APIRouter(prefix="/ops/traces")

@router.get("/{trace_id}/exception-breadcrumbs")
async def get_trace_breadcrumbs(
    trace_id: str,
    trace_svc: SentryTraceService = Depends(get_sentry_trace_service),
    team_member: TeamMember = Depends(get_team_member)
):
    trace_data = await trace_svc.find_by_trace_id(trace_id)
    if not trace_data:
        raise HTTPException(status_code=404, detail="Trace ID not found")
    if trace_data.workspace_id != team_member.workspace_id and not team_member.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to view trace breadcrumbs from another workspace")

    return {
        "trace_id": trace_id,
        "span_count": len(trace_data.spans),
        "breadcrumbs": trace_data.breadcrumbs
    }
